<?php $request = Illuminate\Http\Request::create("/api/v1/devices", "POST", ["customer_id" => 1, "emi_account_id" => null, "display_name" => "Test Device"]); $request->headers->set("X-Company-Id", "1"); $user = App\Models\User::find(273); $request->setUserResolver(function () use ($user) { return $user; }); $response = app(App\Http\Middleware\ResolveCompanyContext::class)->handle($request, function ($req) { $data = ["customer_id" => 1, "emi_account_id" => null, "display_name" => "Test Device"]; try { $device = app(App\Services\DeviceService::class)->register($data, $req->user()); return new Illuminate\Http\JsonResponse(["success" => true, "device_id" => $device->id]); } catch (\Throwable $e) { return new Illuminate\Http\JsonResponse(["error" => $e->getMessage(), "trace" => $e->getTraceAsString()]); } }); echo $response->getContent();
